import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const check = process.argv.includes("--check");
const root = fileURLToPath(new URL("../", import.meta.url));
const jsPath = `${root}/material-symbols-react.js`;
const typesPath = `${root}/material-symbols-react.d.ts`;
const config = JSON.parse(await readFile(`${root}/material-symbols.json`, "utf8"));

const names = [...new Set(config.names)].sort();
const aliases = Object.entries(config.aliases).sort(([a], [b]) => a.localeCompare(b));

for (const [, symbol] of aliases) {
  if (!names.includes(symbol)) {
    throw new Error(`Alias references a symbol outside the approved set: ${symbol}`);
  }
}

const serializedNames = names.map((name) => JSON.stringify(name)).join(",\n  ");
const componentMap = names
  .map((name) => `  ${JSON.stringify(name)}: createMaterialSymbol(${JSON.stringify(name)})`)
  .join(",\n");
const aliasRuntime = aliases
  .map(
    ([exportName, symbol]) =>
      `export const ${exportName} = /* @__PURE__ */ createMaterialSymbol(${JSON.stringify(symbol)}, ${JSON.stringify(exportName)});`,
  )
  .join("\n");
const aliasTypes = aliases
  .map(([exportName]) => `export const ${exportName}: MaterialSymbolComponent;`)
  .join("\n");

const js = `// Generated by scripts/generate-react-icons.mjs. Do not edit manually.
import { createElement, forwardRef } from "react";

export const materialSymbolNames = /* @__PURE__ */ Object.freeze([
  ${serializedNames}
]);

const clamp = (value, min, max, fallback) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(max, Math.max(min, number)) : fallback;
};

function renderMaterialSymbol(name, {
  size = 24,
  fill = false,
  weight = 400,
  grade = 0,
  opticalSize,
  className,
  style,
  title,
  ...props
}, ref) {
  const labelled = Boolean(title || props["aria-label"] || props["aria-labelledby"]);
  const resolvedOpticalSize = clamp(
    opticalSize ?? (typeof size === "number" ? size : 24),
    20,
    48,
    24
  );
  const variationSettings = [
    \`'FILL' \${fill === true ? 1 : clamp(fill, 0, 1, 0)}\`,
    \`'wght' \${clamp(weight, 100, 700, 400)}\`,
    \`'GRAD' \${clamp(grade, -50, 200, 0)}\`,
    \`'opsz' \${resolvedOpticalSize}\`,
  ].join(", ");

  return createElement(
    "span",
    {
      ...props,
      ref,
      title,
      className: ["deslop-material-symbol", className].filter(Boolean).join(" "),
      role: props.role ?? (labelled ? "img" : undefined),
      "aria-hidden": props["aria-hidden"] ?? (labelled ? undefined : true),
      style: {
        fontSize: typeof size === "number" ? \`\${size}px\` : size,
        fontVariationSettings: variationSettings,
        ...style,
      },
    },
    name
  );
}

export const MaterialSymbol = /* @__PURE__ */ forwardRef(function MaterialSymbol(
  { name, ...props },
  ref
) {
  return renderMaterialSymbol(name, props, ref);
});
MaterialSymbol.displayName = "MaterialSymbol";

export const Icon = MaterialSymbol;

export function createMaterialSymbol(name, displayName) {
  const Component = forwardRef(function DeslopMaterialSymbol(props, ref) {
    return renderMaterialSymbol(name, props, ref);
  });
  Component.displayName = displayName ?? \`MaterialSymbol(\${name})\`;
  return Component;
}

export const materialSymbolComponents = /* @__PURE__ */ Object.freeze({
${componentMap}
});

export const iconNames = materialSymbolNames;
export const iconComponents = materialSymbolComponents;
export const getIconComponent = (name) => materialSymbolComponents[name];

${aliasRuntime}
`;

const types = `// Generated by scripts/generate-react-icons.mjs. Do not edit manually.
import type {
  ForwardRefExoticComponent,
  HTMLAttributes,
  RefAttributes,
} from "react";

export const materialSymbolNames: readonly [
  ${serializedNames}
];

export type MaterialSymbolName = (typeof materialSymbolNames)[number];
export type MaterialSymbolBaseProps = Omit<HTMLAttributes<HTMLSpanElement>, "children"> & {
  size?: number | string;
  fill?: boolean | 0 | 1;
  weight?: number;
  grade?: number;
  opticalSize?: number;
};
export type MaterialSymbolProps = MaterialSymbolBaseProps & {
  name: MaterialSymbolName;
};
export type MaterialSymbolComponent = ForwardRefExoticComponent<
  MaterialSymbolBaseProps & RefAttributes<HTMLSpanElement>
>;

export const MaterialSymbol: ForwardRefExoticComponent<
  MaterialSymbolProps & RefAttributes<HTMLSpanElement>
>;
export const Icon: typeof MaterialSymbol;
export function createMaterialSymbol(
  name: MaterialSymbolProps["name"],
  displayName?: string,
): MaterialSymbolComponent;

export const materialSymbolComponents: Readonly<
  Record<MaterialSymbolName, MaterialSymbolComponent>
>;

export const iconNames: typeof materialSymbolNames;
export type IconName = MaterialSymbolName;
export type IconBaseProps = MaterialSymbolBaseProps;
export type IconProps = MaterialSymbolProps;
export type IconComponent = MaterialSymbolComponent;
export const iconComponents: typeof materialSymbolComponents;
export function getIconComponent(name: MaterialSymbolName): MaterialSymbolComponent;
export function getIconComponent(name: string): MaterialSymbolComponent | undefined;

${aliasTypes}
`;

async function verify(path, expected) {
  let actual = "";
  try {
    actual = await readFile(path, "utf8");
  } catch {
    // Report the same actionable error for a missing or stale generated file.
  }

  if (actual !== expected) {
    throw new Error(`${path} is stale; run scripts/generate-react-icons.mjs`);
  }
}

if (check) {
  await verify(jsPath, js);
  await verify(typesPath, types);
  console.log(`${names.length} approved Material Symbols are up to date.`);
} else {
  await writeFile(jsPath, js);
  await writeFile(typesPath, types);
  console.log(`Generated ${names.length} approved Material Symbols.`);
}
